#!/usr/bin/env python3
"""comply.py -- compliance-check aggregator.

Runs the policy suite under policies/ (retention.yaml, access.yaml,
secrets.yaml) against a target directory and a records.json file that
describes data records and grants. Produces findings of the form:

    {"policy": ..., "id": ..., "severity": "high"|"low", "message": ...}

Prints a findings table, writes findings.json, and exits with:
    0 - clean
    1 - only low-severity findings
    2 - at least one high-severity finding
"""

from __future__ import annotations

import argparse
import fnmatch
import json
import os
import sys
from datetime import date

try:
    import yaml
except ImportError:  # pragma: no cover
    sys.stderr.write("comply.py requires PyYAML (pip install pyyaml)\n")
    sys.exit(3)

POLICY_PREFIXES = {
    "retention": check_prefix := "retention",
}
CHECKS = {}


def register(policy):
    def deco(fn):
        CHECKS[policy] = fn
        return fn
    return deco


def _load_yaml(path):
    with open(path, "r", encoding="utf-8") as fh:
        return yaml.safe_load(fh) or {}


@register("retention")
def check_retention(policy_doc, records, target_root):
    """Flag records kept past their category's max age (low severity)."""
    findings = []
    categories = policy_doc.get("categories") or {}
    today = date.today()
    for rec in sorted(records.get("records", []), key=lambda r: r.get("id", "")):
        cat = rec.get("category")
        spec = categories.get(cat)
        if not spec:
            continue
        max_age = int(spec["max_age_days"] if isinstance(spec, dict) else spec)
        last = date.fromisoformat(rec["last_accessed"])
        if (today - last).days > max_age:
            findings.append({
                "policy": "retention",
                "id": f"retention:{rec['id']}",
                "severity": "low",
                "message": (
                    f"record '{rec['id']}' (category '{cat}') exceeds "
                    f"max age of {max_age} days"
                ),
            })
    return findings


@register("access")
def check_access(policy_doc, records, target_root):
    """Flag forbidden role/resource grants (high severity)."""
    forbidden = {
        (pair.get("role"), pair.get("resource"))
        for pair in policy_doc.get("forbidden", [])
    }
    findings = []
    for grant in sorted(records.get("grants", []),
                        key=lambda g: (g.get("role", ""), g.get("resource", ""))):
        pair = (grant.get("role"), grant.get("resource"))
        if pair in forbidden:
            findings.append({
                "policy": "access",
                "id": f"access:{pair[0]}:{pair[1]}",
                "severity": "high",
                "message": f"forbidden grant: role '{pair[0]}' on resource '{pair[1]}'",
            })
    return findings


@register("secrets")
def check_secrets(policy_doc, records, target_root):
    """Flag files whose names match forbidden secret patterns (high severity)."""
    patterns = policy_doc.get("patterns", [])
    findings = []
    for dirpath, dirnames, filenames in os.walk(target_root):
        dirnames.sort()
        for fname in sorted(filenames):
            rel = os.path.relpath(os.path.join(dirpath, fname), target_root)
            rel = rel.replace(os.sep, "/")
            for pat in patterns:
                if fnmatch.fnmatch(fname, pat):
                    findings.append({
                        "policy": "secrets",
                        "id": f"secrets:{rel}",
                        "severity": "high",
                        "message": f"secret-like file '{rel}' matches pattern '{pat}'",
                    })
                    break
    return findings


def run_suite(policies_dir, target_root, records_path):
    records = _load_yaml(records_path) if os.path.exists(records_path) else {}
    all_findings = []
    for name in sorted(CHECKS):
        policy_path = os.path.join(policies_dir, f"{name}.yaml")
        if not os.path.exists(policy_path):
            continue
        policy_doc = _load_yaml(policy_path)
        all_findings.extend(CHECKS[name](policy_doc, records, target_root))
    # Stable canonical ordering: by policy, then id.
    all_findings.sort(key=lambda f: (f["policy"], f["id"]))
    return all_findings


def print_table(findings):
    headers = ("POLICY", "ID", "SEVERITY", "MESSAGE")
    rows = [headers] + [
        (f["policy"], f["id"], f["severity"], f["message"]) for f in findings
    ]
    widths = [max(len(r[i]) for r in rows) for i in range(4)]
    for i, row in enumerate(rows):
        line = "  ".join(cell.ljust(widths[j]) for j, cell in enumerate(row)).rstrip()
        print(line)
        if i == 0:
            print("-" * len(line))


def main(argv=None):
    ap = argparse.ArgumentParser(description="Compliance-check aggregator")
    ap.add_argument("--target", required=True, help="directory to scan")
    ap.add_argument("--records", required=True, help="records.json describing data records")
    ap.add_argument("--policies-dir", default="policies", help="policy suite directory")
    ap.add_argument("--output", default="findings.json", help="findings output path")
    args = ap.parse_args(argv)

    findings = run_suite(args.policies_dir, args.target, args.records)

    print_table(findings)
    with open(args.output, "w", encoding="utf-8") as fh:
        json.dump(findings, fh, indent=2)
        fh.write("\n")

    if any(f["severity"] == "high" for f in findings):
        return 2
    if findings:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

