{
  "records": [
    {"id": "rec-101", "category": "customer_pii", "last_accessed": "2026-08-01"},
    {"id": "rec-102", "category": "audit_logs", "last_accessed": "2026-05-20"}
  ],
  "grants": [
    {"role": "engineer", "resource": "customer_pii"},
    {"role": "auditor", "resource": "audit_logs"}
  ]
}
EOF
echo "quarterly report, nothing to see" > fixtures/clean/target/data/report.txt

# --- low-only: two expired records (two low findings), no highs ---
cat > fixtures/low_only/records.json <<'EOF'
{
  "records": [
    {"id": "rec-201", "category": "customer_pii", "last_accessed": "2020-03-10"},
    {"id": "rec-202", "category": "audit_logs", "last_accessed": "2021-11-02"}
  ],
  "grants": [
    {"role": "auditor", "resource": "audit_logs"}
  ]
}
EOF
echo "archived audit export" > fixtures/low_only/target/data/export.csv

# --- mixed: id_rsa file (high) + same two expired records (lows) ---
